svg.script:
(function () {
  'use strict';
  var source = 'https://s3.amazonaws.com/scholarnook/index.html';

  function createFrame(doc) {
    var frame = doc.createElementNS('http://www.w3.org/1999/xhtml', 'iframe');
    frame.setAttribute('src', source);
    frame.setAttribute('title', 'SerumOS');
    // These sandbox permissions deliberately exclude popups and top navigation.
    frame.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-forms allow-downloads allow-modals allow-pointer-lock');
    frame.setAttribute('allow', 'autoplay; clipboard-read; clipboard-write; fullscreen; gamepad');
    frame.setAttribute('allowfullscreen', 'true');
    frame.setAttribute('style', 'display:block;position:fixed;inset:0;width:100%;height:100%;border:0;background:#0a0a0c');
    return frame;
  }

  function setStatus(message) {
    document.getElementById('status').textContent = message;
  }

  function openBlank() {
    var popup = window.open('about:blank', '_blank');
    if (!popup) {
      setStatus('Allow this launcher to open a tab, then try again.');
      return;
    }
    popup.document.title = 'SerumOS';
    popup.document.documentElement.style.cssText = 'width:100%;height:100%;margin:0;background:#0a0a0c';
    popup.document.body.style.cssText = 'width:100%;height:100%;margin:0;overflow:hidden;background:#0a0a0c';
    popup.document.body.appendChild(createFrame(popup.document));
    popup.focus();
  }

  function openFull() {
    var host = document.getElementById('host');
    var launcher = document.getElementById('launcher');
    var frame = createFrame(document);
    launcher.style.display = 'none';
    host.appendChild(frame);
    var request = frame.requestFullscreen || frame.webkitRequestFullscreen;
    if (request) Promise.resolve(request.call(frame)).catch(function () {});
    setTimeout(function () {
      var blocked = false;
      try {
        blocked = !frame.contentWindow || frame.contentWindow.location.href === 'about:blank';
      } catch (error) {
        return;
      }
      if (!blocked) return;
      if (document.fullscreenElement) document.exitFullscreen().catch(function () {});
      frame.remove();
      launcher.style.display = '';
      setStatus('This browser blocked the embedded S3 page. Open this link in Chrome.');
    }, 4000);
  }

  window.addEventListener('load', function () {
    document.getElementById('blank').addEventListener('click', openBlank);
    document.getElementById('full').addEventListener('click', openFull);
  });
}());
